def review24_test_source():
    """Generated unknown historical attribution controls."""
    return '"""Generated unknown historical attribution controls for Demand24."""\nimport copy\nimport json\nimport unittest\n\nfrom test_review19_repairs import generator\nfrom test_review22_repairs import Review22Harness\n\nCASES = generator.review24_cases()\n\n\nclass Review24Tests(unittest.TestCase):\n    def test_unknown_author_is_absent_and_repeated_screening_is_stable(self):\n        h = Review22Harness()\n        lib, _, _, _ = h.ready()\n        original = copy.deepcopy(CASES["evidence"])\n        fact = lib.evidence_observation(original)\n        self.assertNotIn("author_hash", fact)\n        self.assertTrue(fact["explicit"])\n        self.assertEqual(h.redactor.safe_data(fact), fact)\n        merged = lib.merge_observations({"evidence": [original], "authors": []})\n        self.assertEqual(original, CASES["evidence"])\n        self.assertEqual(merged["reach"], 0)\n        self.assertEqual(merged["internal_mentions"], 0)\n        self.assertEqual(merged["observation_count"], 1)\n        self.assertEqual(merged["independent_source_count"], 1)\n        for item in merged["evidence"] + merged["observation_index"]:\n            self.assertNotIn("author_hash", item)\n        self.assertEqual(h.redactor.safe_data(merged), merged)\n        self.assertEqual(lib.merge_observations(merged), merged)\n\n    def test_legacy_unknown_snippet_survives_serialization_updates_and_replay(self):\n        for legacy_author_count in CASES["legacy_author_counts"]:\n            with self.subTest(legacy_author_count=legacy_author_count):\n                h = Review22Harness()\n                lib, _, _, bot = h.ready()\n                pool = h.pool()\n                incoming = h.demand(CASES["authors"][3])\n                legacy = {key: copy.deepcopy(value) for key, value in incoming.items()\n                          if key not in {"evidence", "observation_index", "authors"}}\n                known = CASES["authors"][:legacy_author_count]\n                legacy.update(\n                    authors=[{"author_hash": author, "urgency": "need", "segment": "free"}\n                             for author in known],\n                    evidence=[copy.deepcopy(CASES["evidence"])],\n                    reach=CASES["legacy_numeric_claim"],\n                    observation_count=CASES["legacy_numeric_claim"])\n                h.files["synthetic-pool"] = (json.dumps(legacy) + "\\n").encode()\n                unknown_id = None\n                for count, author in enumerate(CASES["authors"][3:6], 1):\n                    demand = h.demand(author)\n                    _, row = pool.upsert("synthetic-pool", demand,\n                                         bot._rescorer(lib.DEFAULT_CONFIG))\n                    unknown = [fact for fact in row["observation_index"]\n                               if "author_hash" not in fact]\n                    self.assertEqual(len(unknown), 1)\n                    if unknown_id is None:\n                        unknown_id = unknown[0]["observation_id"]\n                    self.assertEqual(unknown[0]["observation_id"], unknown_id)\n                    snippets = [item for item in row["evidence"]\n                                if item["observation_id"] == unknown_id]\n                    self.assertEqual(len(snippets), 1)\n                    self.assertNotIn("author_hash", snippets[0])\n                    for key, value in CASES["evidence"].items():\n                        self.assertEqual(snippets[0][key], value)\n                    self.assertEqual(row["reach"], legacy_author_count + count)\n                    self.assertEqual({item["author_hash"] for item in row["authors"]},\n                                     set(known + CASES["authors"][3:3 + count]))\n                    self.assertEqual(row["internal_mentions"], count)\n                    self.assertEqual(row["observation_count"], count + 1)\n                    self.assertEqual(h.redactor.safe_data(row), row)\n                    self.assertEqual(pool.load("synthetic-pool", product_id=CASES["product"]), [row])\n                before = copy.deepcopy(row)\n                _, replay = pool.upsert("synthetic-pool", demand,\n                                        bot._rescorer(lib.DEFAULT_CONFIG))\n                self.assertEqual(replay, before)\n\n    def test_legacy_nullable_index_normalizes_without_reassigning_unknown_author(self):\n        h = Review22Harness()\n        lib, _, _, _ = h.ready()\n        fact = lib.evidence_observation(CASES["evidence"])\n        fact["author_hash"] = None\n        snippet = {**copy.deepcopy(CASES["evidence"]),\n                   "observation_id": fact["observation_id"],\n                   "source_id": fact["source_id"], "author_hash": None}\n        legacy = {"authors": [{"author_hash": CASES["authors"][0]}],\n                  "observation_index": [fact], "evidence": [snippet]}\n        before = copy.deepcopy(legacy)\n        merged = lib.merge_observations(legacy)\n        self.assertEqual(legacy, before)\n        self.assertEqual(merged["authors"], legacy["authors"])\n        self.assertEqual(merged["reach"], 1)\n        self.assertEqual(merged["internal_mentions"], 0)\n        self.assertEqual(merged["observation_count"], 1)\n        for item in merged["evidence"] + merged["observation_index"]:\n            self.assertNotIn("author_hash", item)\n            self.assertEqual(item["observation_id"], fact["observation_id"])\n        self.assertEqual(h.redactor.safe_data(merged), merged)\n        self.assertEqual(lib.merge_observations(merged), merged)\n\n    def test_unique_legacy_author_and_explicit_known_author_are_preserved(self):\n        for explicit in (False, True):\n            with self.subTest(explicit=explicit):\n                h = Review22Harness()\n                lib, _, _, _ = h.ready()\n                authors = CASES["authors"][:2 if explicit else 1]\n                evidence = copy.deepcopy(CASES["evidence"])\n                expected = authors[-1]\n                if explicit:\n                    evidence["author_hash"] = expected\n                record = {"authors": [{"author_hash": author} for author in authors],\n                          "evidence": [evidence]}\n                before = copy.deepcopy(record)\n                merged = lib.merge_observations(record)\n                self.assertEqual(record, before)\n                self.assertEqual(merged["reach"], len(authors))\n                self.assertEqual(merged["internal_mentions"], 1)\n                self.assertEqual(merged["observation_count"], 1)\n                self.assertEqual(merged["observation_index"][0]["author_hash"], expected)\n                self.assertEqual(merged["evidence"][0]["author_hash"], expected)\n                self.assertEqual(h.redactor.safe_data(merged), merged)\n                self.assertEqual(lib.merge_observations(merged), merged)\n\n\nif __name__ == "__main__":\n    unittest.main()\n'


def review25_cases():
    """Synthetic stored-pool compatibility and strict-boundary scenarios."""
    import copy
    base = review22_cases()
    product_a, product_b = base["product"], "acme-alt"
    def row(product, key, number, unknown):
        identity = "obs_" + format(number, "064x")
        source_id = "obs_" + format(100 + number, "064x")
        author = None if unknown else base["authors"][1]
        evidence = {
            "observation_id": identity, "source_id": source_id,
            "channel": "feedback", "origin_type": "internal",
            "ts": base["timestamp"], "redacted_snippet": base["text"],
            "author_hash": author,
        }
        fact = {
            "observation_id": identity, "source_id": source_id,
            "source": "feedback", "origin_type": "internal",
            "explicit": True, "author_hash": author,
        }
        result = {
            "canonical_key": key, "title": "Export preview",
            "summary": "Show a preview before exporting the selected items.",
            "status": "new", "first_seen": base["timestamp"],
            "last_seen": base["timestamp"], "final_score": 25,
            "authors": [{"author_hash": base["authors"][0 if unknown else 1]}],
            "evidence": [evidence], "observation_index": [fact],
            "reach": 1, "internal_mentions": 0 if unknown else 1,
            "observation_count": 1, "independent_source_count": 1,
            "source_set": ["feedback"], "metadata": {"retained": "synthetic-history"},
        }
        if product is not None:
            result["product_id"] = product
        return result
    return {
        "products": [product_a, product_b], "timestamp": base["timestamp"],
        "authors": list(base["authors"]), "new_key": "export-new",
        "missing_key": "export-absent",
        "rows": [
            row(product_a, "export-unknown", 1, True),
            row(product_b, "export-unknown", 2, True),
            row(product_a, "export-known", 3, False),
            row(None, "export-legacy", 4, True),
        ],
        "aliases": ["author_hash", "author", "user_id"],
        "new_alias_locations": ["root", "metadata", "evidence", "observation_index", "authors"],
        "rescore_targets": ["new", "known", "unknown"],
        "invalid_ids": [None, "", False, 7, "observation-untyped", "obs_short",
                        "obs_" + "z" * 64],
        "unsupported_authors": [False, [], {}],
        "typed_ids": ["obs_" + "a" * 64, "u_" + "b" * 16],
    }



def review25_test_source():
    'Generated whole-pool legacy compatibility controls.'
    return '"""Generated stored-pool compatibility controls for Demand25."""\nimport copy\nimport json\nimport unittest\n\nfrom test_review19_repairs import generator\nfrom test_review22_repairs import Review22Harness\n\nCASES = generator.review25_cases()\nPATH = "synthetic-pool"\n\n\ndef encoded(rows):\n    return "".join(json.dumps(row, ensure_ascii=False) + "\\n" for row in rows).encode("utf-8")\n\n\ndef decoded(h):\n    return [json.loads(line) for line in h.files[PATH].decode("utf-8").splitlines()]\n\n\ndef expected_rows():\n    # The expected migration changes only the two canonical null author fields.\n    rows = copy.deepcopy(CASES["rows"])\n    for index in (0, 1, 3):\n        for field in ("evidence", "observation_index"):\n            del rows[index][field][0]["author_hash"]\n    return rows\n\n\ndef put_alias(row, location, alias, value):\n    if location == "root":\n        row[alias] = value\n    elif location == "metadata":\n        row.setdefault("metadata", {})[alias] = value\n    else:\n        row[location][0][alias] = value\n\n\nclass Review25Tests(unittest.TestCase):\n    def fixture(self):\n        h = Review22Harness()\n        lib, _, _, bot = h.ready()\n        pool = h.pool()\n        h.files[PATH] = encoded(CASES["rows"])\n        h.atomic_calls = []\n        original = h.modules["data_safety"].atomic_bytes\n        def capture(path, payload):\n            h.atomic_calls.append((path, payload))\n            original(path, payload)\n        h.modules["data_safety"].atomic_bytes = capture\n        return h, lib, bot, pool\n\n    def demand(self, h, product=None, key=None):\n        demand = h.demand(CASES["authors"][5])\n        demand["product_id"] = product or CASES["products"][0]\n        demand["canonical_key"] = key or CASES["new_key"]\n        return demand\n\n    def assert_no_write(self, h, before):\n        self.assertEqual(h.files[PATH], before)\n        self.assertEqual(h.atomic_calls, [])\n\n    def test_load_normalizes_view_without_persisting_or_changing_product_selection(self):\n        h, _, _, pool = self.fixture()\n        before = h.files[PATH]\n        expected = expected_rows()\n        for product in CASES["products"]:\n            with self.subTest(product=product):\n                self.assertEqual(pool.load(PATH, product_id=product),\n                                 [row for row in expected if row.get("product_id") == product])\n        self.assert_no_write(h, before)\n\n    def test_unrelated_insert_in_each_product_persists_all_legacy_rows_without_recounting(self):\n        for product in CASES["products"]:\n            with self.subTest(product=product):\n                h, lib, bot, pool = self.fixture()\n                demand = self.demand(h, product=product)\n                original = copy.deepcopy(demand)\n                action, created = pool.upsert(PATH, demand, bot._rescorer(lib.DEFAULT_CONFIG))\n                self.assertEqual(action, "new")\n                self.assertEqual(demand, original)\n                self.assertEqual(decoded(h), expected_rows() + [created])\n                self.assertEqual(len(h.atomic_calls), 1)\n                self.assertEqual(created["product_id"], product)\n                self.assertEqual(h.redactor.safe_data(decoded(h)), decoded(h))\n\n    def test_unrelated_merge_preserves_other_products_and_unassigned_history(self):\n        h, lib, bot, pool = self.fixture()\n        expected = expected_rows()\n        target = expected[2]\n        action, merged = pool.upsert(\n            PATH, self.demand(h, key=target["canonical_key"]),\n            bot._rescorer(lib.DEFAULT_CONFIG))\n        self.assertEqual(action, "merged")\n        expected[2] = merged\n        self.assertEqual(decoded(h), expected)\n        self.assertEqual(merged["reach"], 2)\n        self.assertEqual(merged["observation_count"], 2)\n        self.assertEqual(merged["internal_mentions"], 2)\n        self.assertEqual(len(h.atomic_calls), 1)\n\n    def test_unknown_target_keeps_unknown_identity_and_replay_is_byte_stable(self):\n        h, lib, bot, pool = self.fixture()\n        demand = self.demand(h, key=CASES["rows"][0]["canonical_key"])\n        action, merged = pool.upsert(PATH, demand, bot._rescorer(lib.DEFAULT_CONFIG))\n        self.assertEqual(action, "merged")\n        unknown_id = CASES["rows"][0]["observation_index"][0]["observation_id"]\n        for field in ("evidence", "observation_index"):\n            unknown = [item for item in merged[field] if item["observation_id"] == unknown_id]\n            self.assertEqual(len(unknown), 1)\n            self.assertNotIn("author_hash", unknown[0])\n        self.assertEqual({author["author_hash"] for author in merged["authors"]},\n                         {CASES["authors"][0], CASES["authors"][5]})\n        self.assertEqual(merged["reach"], 2)\n        self.assertEqual(merged["observation_count"], 2)\n        self.assertEqual(merged["internal_mentions"], 1)\n        expected = expected_rows()\n        expected[0] = merged\n        self.assertEqual(decoded(h), expected)\n        before = h.files[PATH]\n        _, replay = pool.upsert(PATH, demand, bot._rescorer(lib.DEFAULT_CONFIG))\n        self.assertEqual(replay, merged)\n        self.assertEqual(h.files[PATH], before)\n        self.assertEqual(len(h.atomic_calls), 2)\n\n    def test_status_writes_nullable_and_unrelated_targets_with_exact_product_isolation(self):\n        for target_index in (0, 1, 2):\n            with self.subTest(target_index=target_index):\n                h, _, _, pool = self.fixture()\n                expected = expected_rows()\n                target = expected[target_index]\n                self.assertTrue(pool.set_status(PATH, target["canonical_key"], "planned",\n                                                product_id=target["product_id"]))\n                target["status"] = "planned"\n                target["last_seen"] = CASES["timestamp"]\n                self.assertEqual(decoded(h), expected)\n                self.assertEqual(len(h.atomic_calls), 1)\n\n    def test_legacy_attribution_persists_all_rows_and_preserves_unknown_observations(self):\n        for product in CASES["products"]:\n            with self.subTest(product=product):\n                h, _, _, pool = self.fixture()\n                expected = expected_rows()\n                self.assertTrue(pool.attribute_legacy(\n                    PATH, expected[3]["canonical_key"], product_id=product))\n                expected[3]["product_id"] = product\n                self.assertEqual(decoded(h), expected)\n                self.assertEqual(pool.load(PATH, product_id=product),\n                                 [row for row in expected if row.get("product_id") == product])\n                self.assertEqual(len(h.atomic_calls), 1)\n\n    def test_no_matching_status_or_attribution_leaves_original_nullable_bytes(self):\n        h, _, _, pool = self.fixture()\n        before = h.files[PATH]\n        self.assertFalse(pool.set_status(PATH, CASES["missing_key"], "ack",\n                                         product_id=CASES["products"][0]))\n        self.assertFalse(pool.attribute_legacy(PATH, CASES["missing_key"],\n                                               product_id=CASES["products"][0]))\n        self.assert_no_write(h, before)\n\n    def test_new_null_aliases_remain_strict_in_every_location(self):\n        for alias in CASES["aliases"]:\n            for location in CASES["new_alias_locations"]:\n                with self.subTest(alias=alias, location=location):\n                    h, _, _, pool = self.fixture()\n                    before = h.files[PATH]\n                    demand = self.demand(h)\n                    put_alias(demand, location, alias, None)\n                    original = copy.deepcopy(demand)\n                    with self.assertRaisesRegex(ValueError, "invalid author identity type"):\n                        pool.upsert(PATH, demand)\n                    self.assertEqual(demand, original)\n                    self.assert_no_write(h, before)\n\n    def test_rescore_cannot_introduce_null_aliases_on_new_or_merged_rows(self):\n        for target in CASES["rescore_targets"]:\n            for alias in CASES["aliases"]:\n                for location in ("root", "evidence", "observation_index"):\n                    with self.subTest(target=target, alias=alias, location=location):\n                        h, _, _, pool = self.fixture()\n                        before = h.files[PATH]\n                        key = (CASES["rows"][2 if target == "known" else 0]["canonical_key"]\n                               if target != "new" else CASES["new_key"])\n                        def rescore(row):\n                            put_alias(row, location, alias, None)\n                            return row\n                        with self.assertRaisesRegex(ValueError, "invalid author identity type"):\n                            pool.upsert(PATH, self.demand(h, key=key), rescore)\n                        self.assert_no_write(h, before)\n\n    def test_stored_unidentified_or_malformed_observation_does_not_gain_legacy_exception(self):\n        for field in ("evidence", "observation_index"):\n            for identity in CASES["invalid_ids"]:\n                with self.subTest(field=field, identity=identity):\n                    h, _, _, pool = self.fixture()\n                    rows = copy.deepcopy(CASES["rows"])\n                    item = rows[0][field][0]\n                    if identity is None:\n                        del item["observation_id"]\n                    else:\n                        item["observation_id"] = identity\n                    h.files[PATH] = encoded(rows)\n                    before = h.files[PATH]\n                    with self.assertRaisesRegex(ValueError, "invalid author identity type"):\n                        pool.set_status(PATH, rows[2]["canonical_key"], "ack",\n                                        product_id=CASES["products"][0])\n                    self.assert_no_write(h, before)\n\n    def test_stored_null_alias_outside_canonical_slots_remains_strict(self):\n        locations = ("root", "metadata", "authors", "evidence", "observation_index")\n        for location in locations:\n            for alias in CASES["aliases"]:\n                if location in ("evidence", "observation_index") and alias == "author_hash":\n                    continue\n                with self.subTest(location=location, alias=alias):\n                    h, _, _, pool = self.fixture()\n                    rows = copy.deepcopy(CASES["rows"])\n                    put_alias(rows[0], location, alias, None)\n                    h.files[PATH] = encoded(rows)\n                    before = h.files[PATH]\n                    with self.assertRaisesRegex(ValueError, "invalid author identity type"):\n                        pool.set_status(PATH, rows[2]["canonical_key"], "ack",\n                                        product_id=CASES["products"][0])\n                    self.assert_no_write(h, before)\n\n    def test_stored_competing_alias_cannot_replace_unknown_attribution(self):\n        for field in ("evidence", "observation_index"):\n            for alias in ("author", "user_id"):\n                with self.subTest(field=field, alias=alias):\n                    h, _, _, pool = self.fixture()\n                    rows = copy.deepcopy(CASES["rows"])\n                    rows[0][field][0][alias] = CASES["authors"][2]\n                    h.files[PATH] = encoded(rows)\n                    before = h.files[PATH]\n                    with self.assertRaisesRegex(ValueError, "invalid author identity type"):\n                        pool.set_status(PATH, rows[2]["canonical_key"], "ack",\n                                        product_id=CASES["products"][0])\n                    self.assert_no_write(h, before)\n\n    def test_unsupported_stored_author_types_are_not_normalized(self):\n        for field in ("evidence", "observation_index"):\n            for value in CASES["unsupported_authors"]:\n                with self.subTest(field=field, value=value):\n                    h, _, _, pool = self.fixture()\n                    rows = copy.deepcopy(CASES["rows"])\n                    rows[0][field][0]["author_hash"] = copy.deepcopy(value)\n                    h.files[PATH] = encoded(rows)\n                    before = h.files[PATH]\n                    with self.assertRaisesRegex(ValueError, "invalid author identity type"):\n                        pool.set_status(PATH, rows[2]["canonical_key"], "ack",\n                                        product_id=CASES["products"][0])\n                    self.assert_no_write(h, before)\n\n    def test_both_canonical_typed_id_formats_preserve_unknown_and_counts(self):\n        for identity in CASES["typed_ids"]:\n            with self.subTest(identity=identity):\n                h, _, _, pool = self.fixture()\n                rows = copy.deepcopy(CASES["rows"])\n                for field in ("evidence", "observation_index"):\n                    rows[0][field][0]["observation_id"] = identity\n                h.files[PATH] = encoded(rows)\n                expected = expected_rows()\n                for field in ("evidence", "observation_index"):\n                    expected[0][field][0]["observation_id"] = identity\n                self.assertTrue(pool.set_status(PATH, rows[2]["canonical_key"], "ack",\n                                                product_id=CASES["products"][0]))\n                expected[2]["status"] = "ack"\n                self.assertEqual(decoded(h), expected)\n\n    def test_conflicting_legacy_attribution_preserves_original_bytes(self):\n        for conflict in ("duplicate-legacy", "attributed"):\n            with self.subTest(conflict=conflict):\n                h, _, _, pool = self.fixture()\n                rows = copy.deepcopy(CASES["rows"])\n                extra = copy.deepcopy(rows[3])\n                if conflict == "attributed":\n                    extra["product_id"] = CASES["products"][0]\n                rows.append(extra)\n                h.files[PATH] = encoded(rows)\n                before = h.files[PATH]\n                with self.assertRaisesRegex(ValueError, "legacy attribution conflicts"):\n                    pool.attribute_legacy(PATH, rows[3]["canonical_key"],\n                                          product_id=CASES["products"][0])\n                self.assert_no_write(h, before)\n\n\nif __name__ == "__main__":\n    unittest.main()\n'


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", type=Path,
                    default=Path(__file__).resolve().parents[1] / "skills/demand-mining/tests/fixtures")
    args = ap.parse_args()
    args.out.mkdir(parents=True, exist_ok=True)
    (args.out / "repair_cases.json").write_text(
        json.dumps(fixtures(), indent=2, sort_keys=True) + "\n", encoding="utf-8")
    (args.out / "review21_cases.json").write_text(
        json.dumps(review21_cases(), indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    (args.out / "review22_cases.json").write_text(
        json.dumps(review22_cases(), indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    (args.out.parent / "test_review22_repairs.py").write_text(review22_test_source(), encoding="utf-8")
    (args.out / "review23_cases.json").write_text(
        json.dumps(review23_cases(), indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    (args.out.parent / "test_review23_repairs.py").write_text(review23_test_source(), encoding="utf-8")
    (args.out / "review24_cases.json").write_text(
        json.dumps(review24_cases(), indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    (args.out.parent / "test_review24_repairs.py").write_text(review24_test_source(), encoding="utf-8")
    (args.out / "review25_cases.json").write_text(
        json.dumps(review25_cases(), indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    (args.out.parent / "test_review25_repairs.py").write_text(review25_test_source(), encoding="utf-8")


if __name__ == "__main__":
    main()
